/*
 * A106599  Irregular triangle read by rows generated by the morphism 1->56,
 *          2->4, 3->5, 4->2, 5->3, 6->12 starting from 1.
 * https://oeis.org/A106599
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl, easy
 * Formula:   not stated
 * Range:     u8 n <= 9307, u16 n <= 9307, u32 n <= 9307, u64 n <= 9307,
 *            u128 n <= 9307, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A106599: irregular triangle read by rows.
   Generated by morphism 1->56, 2->4, 3->5, 4->2, 5->3, 6->12
   starting from the single symbol 1.  The sequence is the
   concatenation of successive rows of the triangle.  */
seq_t a(idx_t n)
{
    /* Max row length needed for n up to ~10000 is below 200. */
    int curr[200];
    int nxt[200];
    int curr_len = 1;
    curr[0] = 1;                      /* first row */
    idx_t pos = 0;                    /* current index in the flattened triangle */

    while (1) {
        /* Scan the current row. */
        for (int i = 0; i < curr_len; ++i) {
            if (pos == n)
                return (seq_t)curr[i];
            ++pos;
        }

        /* Build the next row from the current one. */
        int next_len = 0;
        for (int i = 0; i < curr_len; ++i) {
            int d = curr[i];
            switch (d) {
                case 1:  nxt[next_len++] = 5; nxt[next_len++] = 6; break;
                case 2:  nxt[next_len++] = 4;               break;
                case 3:  nxt[next_len++] = 5;               break;
                case 4:  nxt[next_len++] = 2;               break;
                case 5:  nxt[next_len++] = 3;               break;
                case 6:  nxt[next_len++] = 1; nxt[next_len++] = 2; break;
            }
        }
        /* Prepare for next iteration. */
        curr_len = next_len;
        for (int i = 0; i < curr_len; ++i)
            curr[i] = nxt[i];
    }
}
